// Original single-CoreWindow Win32 message bridge. No native desktop HWND APIs.
// One fullscreen surface; partial raw mouse support. Desktop child windows/IME remain unsupported.
#include <windows.h>
#include <string>
#include <vector>
#include <deque>
#include <memory>
#include <mutex>
#include <condition_variable>
#include <cstring>
